(OUT/'Harness.cs').write_text(r'''
using System;using System.Linq;using System.Collections.Generic;using Newtonsoft.Json.Linq;using Sdt.UI.Screens.Battle;using Sdt.Core;using Sdt.Core.Battle;
namespace Sdt.Core {public class CardDef {public bool area,random;}}
namespace Sdt.Core.Battle {public class FoeIntent {public string icon,label;public int damage,hits=1,bleedBonus;public bool HasDamage=true;public string Icon=>icon;public string Label=>label;public int Damage=>damage;}public class FoeSnapshot {public bool Dead;public int Hp;}public static class BattleRules {public static bool IsAreaEffect(CardDef c)=>c.area;public static bool IsRandomEnemyEffect(CardDef c)=>c.random;}}
namespace Sdt.UI.Screens.Battle {public class StatusChip{public string Name,Icon,Value,Desc;public bool IsCurse;}}
class Program {static int count;static void Check(bool ok,string label){if(!ok)throw new Exception(label);count++;}static void Main(string[] args){
 var source=JObject.Parse(System.IO.File.ReadAllText(args[0]));var input=source["input"].ToObject<Dictionary<string,int>>();var statuses=CurrentBattleStatusModel.Project(input);Check(statuses.Count==(source["statuses"] as JArray).Count,"status count/order");
 for(int i=0;i<statuses.Count;i++){var actual=statuses[i];var expected=source["statuses"][i];Check(actual.Key==(string)expected["key"]&&actual.Name==(string)expected["name"]&&actual.Icon==(string)expected["icon"]&&actual.Amount==(string)expected["amount"]&&actual.Unit==(string)expected["unit"]&&actual.Label==(string)expected["label"],"source status "+actual.Key);}
 Check(CurrentBattleStatusModel.Project(new Dictionary<string,int>{{"atkUp",0},{"bleed",-2},{"unknown",3}}).Count==0,"inactive/unknown hidden");
 foreach(var row in source["effects"]){var actual=BattlePlayerEffects.Project(row["input"].ToObject<BattlePlayerEffectState>());var expected=row["expected"];Check(actual.Count==expected.Count()&&actual.Select((a,i)=>a.Key==(string)expected[i]["key"]&&a.Name==(string)expected[i]["name"]&&a.Icon==(string)expected[i]["icon"]&&a.Duration==(string)expected[i]["duration"]&&a.Description==(string)expected[i]["description"]).All(ok=>ok),"source player effect state "+row["input"]);}
 var effectList=BattlePlayerEffects.Project(new BattlePlayerEffectState{ExtraTurn=true});var effectsOnly=CurrentBattleStatusModel.Project(null,effectList);Check(effectsOnly.Single().Key=="effect:extraTurn"&&effectsOnly[0].Label=="额外回合 待触发","effect-only player chips preserve source key/name/duration");Check(CurrentBattleStatusModel.Project(input,effectList).Last().Key=="effect:extraTurn","effects append after base statuses");bool readOnly=false;try{((IList<BattlePlayerEffect>)effectList).Clear();}catch(NotSupportedException){readOnly=true;}Check(readOnly,"effect snapshot collection read-only");
 Check(CurrentBattleStatusModel.Legacy(new[]{new StatusChip{Name="中毒",Value="7",Icon="[[icon:skull]]",IsCurse=true}}).Single().Label=="中毒 7层","legacy callers share source mechanism icon/units");
 foreach(var expected in source["intents"]){var raw=expected["input"];var intent=new FoeIntent{icon=(string)raw["icon"],label=(string)raw["label"],damage=(int?)raw["damage"]??0,hits=(int?)raw["hits"]??1,bleedBonus=(int?)raw["bleedBonus"]??0,HasDamage=(bool)expected["hasDamage"]};Check(CurrentBattleNameplate.IntentText(intent,false,false)==(string)expected["text"],"source intention text");Check(CurrentBattleNameplate.IntentDescription(intent,false,false)==(string)expected["summary"],"source intention summary");}
 Check(CurrentBattleNameplate.IntentText(new FoeIntent{icon="[[icon:swords]]",damage=9},true,false)=="[[icon:status-freeze]]","freeze overrides damage with passive mechanism icon");Check(CurrentBattleNameplate.IntentText(new FoeIntent(),false,true)=="","dead intent hidden");
 float h;var positions=CurrentBattleStatusLayout.Arrange(new float[]{50,50,50,50,50},150,true,out h);Check(CurrentBattleStatusLayout.ViewportHeight(true)==28&&CurrentBattleStatusLayout.ViewportHeight(false)==59,"source fixed densities");Check(positions[0].Y==1&&positions[1].X==57&&positions[2].Y==32&&h==90,"source wrapping/padding/gaps with scroll overflow");Check(positions.All(p=>p.X>=0&&p.X+p.Width<=150),"no status exceeds viewport width");CurrentBattleStatusLayout.Arrange(new float[]{50,50,50,50},150,false,out h);Check(h==59,"two-row player region remains59");
 var foes=new[]{new FoeSnapshot{Dead=true,Hp=0},new FoeSnapshot{Dead=false,Hp=0},new FoeSnapshot{Hp=3}};Check(CurrentBattleDropProjection.SubmitTarget("enemy","any",-2,foes)==2,"area field drops submit first live positive-HP foe");Check(CurrentBattleDropProjection.SubmitTarget("self","any",-2,foes)==-1,"self field drop preserves side");Check(CurrentBattleDropProjection.SubmitTarget(null,"any",-2,foes)==-2,"pure AOE no-target remains no-target");Check(CurrentBattleDropProjection.SubmitTarget("enemy","any",-2,new FoeSnapshot[0])==-2,"empty battlefield never fabricates an enemy target");Check(CurrentBattleDropProjection.FieldPlayable(new CardDef{area=true},"enemy")&&CurrentBattleDropProjection.FieldPlayable(new CardDef{random=true},"enemy")&&!CurrentBattleDropProjection.FieldPlayable(new CardDef(),"enemy"),"only source field-playable families use empty field");
 Console.WriteLine("PASS "+count+" current-source status/intent/layout/drop assertions");
}}
''',encoding='utf-8')
files=list(OUT.glob('*.cs'))+[ROOT/'Assets/Scripts/Sdt.UI/Screens/Battle'/name for name in ['CurrentBattleStatusModel.cs','CurrentBattleStatusLayout.cs','CurrentBattleDropProjection.cs']]
jsondll=list((ROOT/'Library/PackageCache').glob('com.unity.nuget.newtonsoft-json@*/Runtime/Newtonsoft.Json.dll'))[0];sources=''.join(f'<Compile Include="{escape(str(p))}" />' for p in files)
project=OUT/'Behavior.csproj';project.write_text(f'<Project Sdk="Microsoft.NET.Sdk"><PropertyGroup><OutputType>Exe</OutputType><TargetFramework>net8.0</TargetFramework><EnableDefaultCompileItems>false</EnableDefaultCompileItems><LangVersion>9</LangVersion><NoWarn>CS0649</NoWarn></PropertyGroup><ItemGroup>{sources}<Reference Include="Newtonsoft.Json"><HintPath>{escape(str(jsondll))}</HintPath></Reference></ItemGroup></Project>',encoding='utf-8');(OUT/'NuGet.Config').write_text('<configuration><packageSources><clear /></packageSources></configuration>',encoding='utf-8')
r=subprocess.run(['dotnet','run','--project',str(project),'-p:UseSharedCompilation=false','--',str(HERE/'source-vectors.json')],capture_output=True,text=True,encoding='utf-8',errors='replace',env={**os.environ,'DOTNET_CLI_TELEMETRY_OPTOUT':'1','DOTNET_CLI_UI_LANGUAGE':'en-US'});(OUT/'latest.log').write_text(r.stdout+r.stderr,encoding='utf-8');print(r.stdout+r.stderr);raise SystemExit(r.returncode)
